import { Metaballs, type MetaballsProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#3a3a5c", "#52527a", "#8a8a95"];

interface ShaderMetaballsProps
  extends Omit<MetaballsProps, "frame" | "ref"> {}

function ShaderMetaballsBase({
  speed = 1,
  colorBack = "#12121a",
  colors = NEUTRAL_COLORS,
  count = 10,
  size = 0.83,
  className,
  ...rest
}: ShaderMetaballsProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-metaballs"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <Metaballs
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colors={colors}
        count={count}
        size={size}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  count: {
    type: "number",
    min: 1,
    max: 20,
    step: 1,
    default: 10,
    description: "Count",
    hiddenFromList: false,
  },
  size: {
    type: "number",
    min: 0.2,
    max: 1.5,
    step: 0.05,
    default: 0.83,
    description: "Size",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","count","size","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  count: 10,
  size: 0.83,
  colorBack: "#12121a",
};

type ShaderMetaballsElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderMetaballsBase>;

const ShaderMetaballsInner = forwardRef<
  HTMLDivElement,
  ShaderMetaballsElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderMetaballs>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderMetaballsBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderMetaballsBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderMetaballs = Interactive.withSchema({
  Component: ShaderMetaballsInner,
  componentName: "<ShaderMetaballs>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
